/* Wealth's Atlas desk. Data comes from dated, strict-owner captures. Writes stay local. */
globalThis.createWealthAtlas=function(api){
 const {state,E,money,compact,modal,render:baseRender,navigate}=api,C=wealthCore,D=wealthCaptureData,owner=D.ownerId;
 const ui={month:'',work:'tasks',workAccount:null,workMonth:'',movement:'cohort',signal:'aml',lens:'reviews',review:'due',selected:null,product:null,capital:'coverage',intel:'care',q:'',day:null};
 const active=()=>state.style==='atlas'&&state.persona==='wealth';
 const viewStorageKey='wealth.view.'+owner;
 Object.assign(ui,api.read(viewStorageKey,{}));let lastRouteView='';
 function syncRouteView(){const raw=new URL(location.href).searchParams.get('wealth');if(!raw||raw===lastRouteView)return;try{const saved=JSON.parse(raw);if(saved.ownerId===owner&&saved.view&&typeof saved.view==='object')for(const key of Object.keys(ui))if(key in saved.view)ui[key]=saved.view[key];lastRouteView=raw;}catch{}}
 function render(replace=false){api.write(viewStorageKey,ui);const url=new URL(location.href),raw=JSON.stringify({ownerId:owner,view:ui});url.searchParams.set('wealth',raw);history[replace?'replaceState':'pushState'](null,'',url);lastRouteView=raw;baseRender();}

 const source=k=>D.sources[k],rows=k=>C.rows(source(k),owner),one=k=>rows(k)[0]||{};
 const accounts=()=>D.accounts||[],account=id=>accounts().find(a=>a.Id===id)||api.accounts().find(a=>a.Id===id),name=id=>account(id)?.Name||D.references?.find(a=>a.Id===id)?.Name||'Customer record '+String(id).slice(-5);
 const count=v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:0});
 const num=(v,fmt=count)=>C.number(v)==null?'Unavailable':fmt(Number(v));
 const cash=v=>num(v,money),pct=v=>C.number(v)==null?'Unavailable':Number(v).toFixed(1)+'%';
 const localDateTime=v=>{if(!v)return '';const d=new Date(v);return Number.isNaN(d.getTime())?'':new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
 const when=v=>v?new Date(v).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}):'Time not supplied';
 const cents=v=>C.number(v)==null?'Unavailable':Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2});
 const date=v=>v?new Date(String(v).slice(0,10)+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Date not supplied';
 const btn=(text,action,id='',extra='',cls='secondary')=>`<button class="${cls}" data-wa="${action}" data-wa-id="${E(id)}" ${extra}>${E(text)}</button>`;
 const pill=(s,cls='')=>`<span class="wa-pill ${cls}">${E(s)}</span>`;
 const metric=(label,value,detail='')=>`<div class="wa-metric"><span>${E(label)}</span><strong>${E(value)}</strong><small>${E(detail)}</small></div>`;
 const empty=(label='No records returned for this captured slice.')=>`<div class="wa-empty">${E(label)}</div>`;
 const scope=k=>{const s=source(k),labels={wealthWhoToCall_rowsSql:'Advisor priorities',wealthWhoToCall_summarySql:'Advisor priority summary',planSignals_summarySql:'MoneyGuidePro plan summary',planSignals_atRiskRowsSql:'MoneyGuidePro planning attention',planSignals_reviewRowsSql:'MoneyGuidePro reviews',home_heldAwaySql:'Plaid investable assets',home_heldAwayTotalSql:'Plaid investment summary',digitalLeakage_rowsSql:'Digital platform assets',digitalLeakage_summarySql:'Digital asset summary',whitespace_offersSql:'Wealth product opportunities',holdingsConcentration_rowsSql:'FinServ position weights',tradingPulse_weeklySql:'Confirmed USD weekly trades',transactionSignals_amlChangeSql:'WorldCheck rating changes',transactionSignals_callSentimentSql:'Gong conversation signals',transactionSignals_largeInflowSql:'Transaction observations',campaignTouches_campaignTouchSql:'Marketing engagement',jobChangeSignals_liquidityRowsSql:'UserGems career events'},label=labels[k]||k.includes('_')?(labels[k]||({transactions:'Financial transactions',trades:'Executed trades',interactions:'Source interactions',notes:'Source meeting notes',campaigns:'Campaign history',property:'Property observations',screening:'Screening evidence'}[k.split('_').at(-1)]||'Customer source evidence')):k;return `<p class="wa-source">${E(s?.status==='available'?`Captured ${D.capturedAt} · ${label} · advisor book · ${s.rows.length} returned${s.limit?' · limit '+s.limit:''}`:`${label}: unavailable in this capture`)}${s?.period?' · '+E(s.period):''}</p>`;};
 const panel=(title,body,desc='',cls='')=>`<section class="wa-panel ${cls}"><header><div><h2>${E(title)}</h2>${desc?`<p>${E(desc)}</p>`:''}</div></header>${body}</section>`;
 const tabs=(items,key)=>`<div class="wa-tabs" role="group" aria-label="Choose view">${items.map(([v,l])=>`<button data-wa="tab" data-wa-key="${key}" data-wa-value="${v}" aria-pressed="${ui[key]===v}" class="${ui[key]===v?'selected':''}">${E(l)}</button>`).join('')}</div>`;
 function rowAccountKey(r,key){return key==='relationshipGraph_warmIntroSql'?r.src_id:key==='businessOwners_handoffRowsSql'?r.biz_id:C.accountKey(r);}
 function findRow(key,id){return rows(key).find(r=>rowAccountKey(r,key)===id);}
 function provenance(kind,r){const id=rowAccountKey(r,kind);return {...(r.dst_id?{introductionKey:`graph:${r.src_id}:${r.dst_id}`,referrerAccountId:r.src_id,targetAccountId:r.dst_id}:{}),...(r.biz_id?{targetAccountId:r.owner_id,referrerAccountId:r.biz_id}:{}),accountId:id,sourceAccountId:id,sourceKind:kind,sourceKey:`${kind}:${id}:${r.period||r.next_review||r.nextReview||r.trade_date||D.capturedAt}`,notes:`${kind} source captured ${D.capturedAt}; advisor-scoped. Review the evidence and confirm needs before outreach.`};}
 function action(r,kind,key,label='Prepare outreach'){const id=rowAccountKey(r,key);return `${btn(label,'propose',id,`data-wa-source="${E(key)}" data-wa-kind="${E(kind)}"`,'primary')}${btn('Open 360','customer',id)}`;}
 function householdRow(r,key,detail,actionKind='task'){const id=rowAccountKey(r,key);return `<article class="wa-workrow"><button class="wa-person" data-wa="select" data-wa-id="${E(id)}"><span class="wa-avatar">${E(api.initials(name(id)))}</span><span><strong>${E(name(id))}</strong><small>${E(detail)}</small></span></button><div class="wa-rowactions">${btn('Review','evidence',id,`data-wa-source="${E(key)}"`)}${btn('360','customer',id)}</div></article>`;}
 const offers=()=>{const allowedCodes=new Set(D.products.flatMap(p=>p.codes));const allowed=new Set(accounts().map(a=>a.Id));let all=[];for(const id of allowed)all.push(...C.selectOffers([{rows:D.offers||[],label:'Native eligibility Nov 13'},{rows:api.baseOffers(),label:'Eligibility capture Nov 12'}],id,allowed));return all.filter(o=>allowedCodes.has(o.code));};
 const offersForAccount=id=>offers().filter(r=>r.account===id);
 const historyFor=o=>C.history([...(D.offerHistory||[]),...workspaceDC.datasets.offerHistory],o);
 const holdings=id=>(D.financialAccounts||[]).filter(r=>r.FinServ__PrimaryOwner__c===id);
 const owned=(id,code)=>C.owned(holdings(id),code);
 function offerLabel(o){return api.offerLabels[o.code]||D.offerLabels?.[o.code]||o.code;}
 function existingOpportunity(o){return C.existingGridOpportunity(D.opportunities||[],o.account,offerLabel(o));}
 function offerEvidence(o){const h=historyFor(o),values=h.map(r=>Number(r.probability)),max=Math.max(100,...values);return `<div class="wa-offer"><div>${pill(offerLabel(o))}<h3>${pct(o.probability)}<small>modeled conversion</small></h3><div class="wa-meter"><i style="width:${Math.max(0,Math.min(100,Number(o.probability)||0))}%"></i></div></div><div class="wa-pair">${metric('Modeled expected value',cash(o.value),'Modeled value, not opportunity amount')}${metric('Recommendation rank',o.rank==null?'Not ranked':String(o.rank),'Confirm needs and ownership')}</div>${scoreHistory(o)}<div class="wa-actions">${btn('Prepare follow-up','offer-task',o.account,`data-wa-code="${E(o.code)}"`,'primary')}${!owned(o.account,o.code)&&o.rank!=null&&!existingOpportunity(o)?btn('Propose opportunity','offer-opportunity',o.account,`data-wa-code="${E(o.code)}"`):pill(existingOpportunity(o)?'A grid opportunity is already open':'Review current ownership')}${btn('Open household','customer',o.account)}</div><p class="wa-source">Account + product stay linked through the proposal. A local proposal is not an approved offer, appointment or CRM record.</p></div>`;}
 function selectedOffer(id){const os=offersForAccount(id);return os.find(o=>o.code===ui.product)||os[0];}
 function productPicker(id){const os=offersForAccount(id),o=selectedOffer(id);return `<label class="wa-field">Product<select data-wa-select="product" data-wa-account="${E(id)}">${os.map(x=>`<option value="${E(x.code)}" ${o?.code===x.code?'selected':''}>${E(offerLabel(x))}</option>`).join('')}</select></label>`;}
 function directory(){const q=String(state.q||ui.q||'').trim().toLowerCase(),rs=accounts().filter(a=>!q||[a.Name,a.PersonEmail,a.Id].some(v=>String(v||'').toLowerCase().includes(q))),shown=rs.slice(0,12),selected=account(ui.selected)||shown[0],p=allPlans().find(p=>p.account_id===selected?.Id);return `<div class="wa">${title('My relationships','Find the household, then pick up the conversation where it matters.')}<div class="wa-directorybar"><label class="wa-field">Search my captured book<input data-wa-directory value="${E(state.q||ui.q||'')}" placeholder="Name, email or exact record"></label><div>${metric('Captured households',String(accounts().length),'Verified owner; source sample')}${metric('Matching search',String(rs.length),q?'Refine to find an exact household':'Search works across the capture')}</div></div><div class="wa-directorylayout"><div class="wa-directorycards">${shown.map(a=>{const plan=allPlans().find(p=>p.account_id===a.Id),hs=holdings(a.Id);return `<article class="${a.Id===selected?.Id?'selected':''}"><button data-wa="select" data-wa-id="${E(a.Id)}"><span class="wa-avatar">${E(api.initials(a.Name))}</span><span><strong>${E(a.Name)}</strong><small>${E(a.PersonEmail||'Household record')} · …${E(a.Id.slice(-5))}</small></span></button><div class="wa-directorysignals">${plan?`<span>${pct(plan.success)} plan success</span><div class="wa-meter"><i style="width:${Math.max(0,Math.min(100,Number(plan.success)||0))}%"></i></div>`:`<span>${hs.length} financial accounts in this capture</span>`}</div>${btn('Open 360','customer',a.Id,'','text-button')}</article>`;}).join('')||empty('No matching captured households. Try a shorter name or an exact ID.')}</div><aside class="wa-panel wa-directoryfocus">${selected?`<span class="wa-avatar">${E(api.initials(selected.Name))}</span><h2>${E(selected.Name)}</h2><p>${E(selected.PersonEmail||'Contact email not captured')}</p>${p?`<div class="wa-pair">${metric('Plan success',pct(p.success),'MoneyGuidePro modeled')}${metric('Next review',date(p.next_review),'Provider date')}</div>`:empty('No plan-health row in this bounded source capture.')}<div class="wa-actions">${btn('Open household','customer',selected.Id,'','primary')}${btn('Build review folio','folio',selected.Id)}</div>${btn('Plan follow-up','quick-task',selected.Id)}`:empty()}</aside></div><p class="wa-source">Showing up to12 matches. Search narrows all${accounts().length} captured records immediately; this is not an exhaustive live directory.</p></div>`;}
 function journey(){const ev=workspaceCapture.personas.wealth.lifeEvents||[],month=ui.month||ev.map(e=>String(e.EventDate).slice(0,7)).sort().at(-1)||D.asOfDate.slice(0,7),months=[...new Set([...ev.map(e=>String(e.EventDate).slice(0,7)),'2026-11'])].sort(),es=ev.filter(e=>String(e.EventDate).startsWith(month));const totalGoals=(D.goals||[]).reduce((s,g)=>s+(Number(g.TargetAmount)||0),0);return `<div class="wa">${title('Plans & turning points','See the person behind the plan, then prepare for what comes next.')}<div class="wa-actions">${btn('Log life event','new-life','','','primary')}</div><div class="wa-journeylayout"><div>${panel('Moments on my calendar',`<label class="wa-field">Month<select data-wa-month>${months.map(m=>`<option value="${m}" ${m===month?'selected':''}>${E(new Date(m+'-01T12:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'}))}</option>`).join('')}</select></label>${calendar(es.map(e=>({account_id:e.PrimaryPerson?.AccountId,next_review:String(e.EventDate).slice(0,10)})),month)}<p class="wa-source">Recorded life-event dates, not appointments. ${ev.length} selected source moments.</p>`)}${panel('Goals in this capture',`<div class="wa-pair">${metric('CRM goals',String((D.goals||[]).length),'Two verified households')}${metric('Target amount',cash(totalGoals),'Selected CRM goals')}</div>${btn('Create goal proposal','new-goal','','','primary')}`,'Goal targets are separate from provider plan totals.')}</div><div>${panel('The people behind the milestones',`<div class="wa-moments">${es.map(e=>{const id=e.PrimaryPerson?.AccountId,labels={Graduation:['A new chapter','Education and the next independence conversation'],Job:['Work is changing','Revisit benefits, savings and long-term plans'],Baby:['A family milestone','Review priorities together'],Retirement:['A different pace','Income, liquidity and the next chapter']},copy=labels[e.EventType]||['A moment that matters','Understand what this changes for the plan'];return `<article class="wa-moment wa-moment-${E(e.EventType?.toLowerCase())}"><div class="wa-momentdate"><b>${new Date(e.EventDate).getUTCDate()}</b><span>${new Date(e.EventDate).toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}</span></div><div><small>${E(e.EventType)} · ${E(copy[0])}</small><h3>${E(name(id))}</h3><p>${E(e.Name)}</p><span>${E(copy[1])}</span><div class="wa-actions">${btn('Review life event','life-edit',e.Id)}${btn('Open household','customer',id)}${btn('Prepare follow-up','quick-task',id,'','text-button')}</div></div></article>`;}).join('')||empty('No captured milestones in this month. Choose another month to explore source events.')}</div>`,'Dates and Contact links are captured records; conversation prompts are preparation, not inferred family roles.')}${panel('Goals I can work on',`${[...new Set((D.goals||[]).map(g=>g.FinancialPlan?.AccountId))].map(id=>`<h3>${E(name(id))}</h3>${goalCards(id)}`).join('')}`)}</div></div></div>`;}
 function attentionVisual(){const p=one('planSignals_summarySql'),total=C.number(p.plans),critical=C.number(p.critical),risk=C.number(p.at_risk);if(!total)return empty('The plan summary is unavailable.');const normal=total-risk,watch=risk-critical;return `<div class="wa-attention"><div class="wa-attentionbar" role="img" aria-label="${critical} critical plans, ${watch} other plans below70percent, ${normal} at or above70percent"><i class="critical" style="flex:${critical}"></i><i class="watch" style="flex:${watch}"></i><i class="steady" style="flex:${normal}"></i></div><div><span><i class="critical"></i>${num(critical)} below50%</span><span><i class="watch"></i>${num(watch)} 50–69%</span><span><i class="steady"></i>${num(normal)} ≥70%</span></div></div>`;}
 function pipelineStrip(){const ss=(D.pipelineStages||[]).filter(s=>Number(s.n)>0).sort((a,b)=>Number(b.amount)-Number(a.amount)),total=ss.reduce((s,r)=>s+Number(r.amount||0),0),n=ss.reduce((s,r)=>s+Number(r.n||0),0);return `<section class="wa-pipelineband"><div><span>My open pipeline</span><strong>${cash(total)}</strong><small>${num(n)} open opportunities · CRM aggregate</small></div><div class="wa-stageview"><div class="wa-stageline" role="img" aria-label="Pipeline by recorded opportunity stage">${ss.map((r,i)=>`<i style="flex:${Math.max(0,Number(r.amount))};background:hsl(${250+i*7} ${35+i%3*8}% ${37+i%5*6}%)" title="${E(r.StageName)} · ${cash(r.amount)} · ${num(r.n)} opportunities"></i>`).join('')}</div><div>${ss.slice(0,3).map(r=>`<span>${E(r.StageName)} <b>${cash(r.amount)}</b></span>`).join('')}</div></div>${btn('Open pipeline','page','pipeline')}</section>`;}
 function capitalPath(id){const outside=findRow('home_heldAwaySql',id),fin=holdings(id),held=fin.filter(h=>/Brokerage|Managed|IRA|529/i.test(h.Name||''));return `<div class="wa-capitalpath"><div><span>Outside investments</span><strong>${outside?cash(outside.balance):'Not captured'}</strong><small>${E(outside?.institution||'No investable held-away row in this sample')}</small></div><i aria-hidden="true">↔</i><div class="wa-capitalhub"><span class="wa-avatar">${E(api.initials(name(id)))}</span><strong>${E(name(id))}</strong><small>My household conversation</small></div><i aria-hidden="true">↔</i><div><span>Investment accounts on file</span><strong>${held.length}</strong><small>Separate from lending / deposits</small></div></div><p class="wa-source">A conversation map, not a movement-of-funds instruction. Source balances and modeled product values stay separate.</p>`;}

 function agenda(){const rs=(D.agenda||[]).map(a=>({...findRow(a.sourceDataset,a.clientId),...a,account_id:a.clientId})),first=rs[0],ps=one('planSignals_summarySql'),ha=one('home_heldAwayTotalSql'),trade=rows('tradingPulse_weeklySql').at(-1);return `<div class="wa"><section class="wa-hero"><div><p class="wa-kicker">My advisory desk · ${E(D.capturedAt)}</p><h1>Make the next conversation count.</h1><p>Review the plans that need attention, see where capital sits, and choose the right first call.</p><div class="wa-pulse">${metric('Outside investable assets',cash(ha.balance),'Active brokerage + robo')}${metric('Plans below 70%',num(ps.at_risk),'Modeled plan success')}${metric('Latest full-week net flow',cash(D.netFlow?.last?.net),'Credits − debits · '+date(D.netFlow?.last?.week))}</div></div><aside>${pill('My first move')}${first?`<h2>${E(name(first.account_id))}</h2><p>${E(first.action)}</p><small>Act by ${date(first.dueDate)} · ${E(first.source)}</small><div class="wa-actions">${action(first,'task',first.sourceDataset,'Prepare my first move')}</div>${btn('Why this household?','evidence',first.account_id,`data-wa-source="${E(first.sourceDataset)}"`,'text-button')}`:empty()}</aside></section>${pipelineStrip()}<div class="wa-two"><div>${panel('My advisor agenda',rs.slice(0,6).map(r=>householdRow(r,r.sourceDataset,`${r.action} · act by ${date(r.dueDate)}`)).join('')+scope('wealthWhoToCall_rowsSql'),'Native queue ranking, source action and due date; inspect the evidence before acting.')}</div><div>${panel('The review horizon',`${attentionVisual()}${tabs([['due','Due soon'],['critical','Plan rescue'],['stale','Refresh']], 'review')}${miniReviews()}${btn('Open review horizon','page','health')}`,'Provider reviews and planning signals, separate from booked appointments.')}${panel('Trading conversations',trade?`<div class="wa-pair">${metric('Latest-week buys',cash(trade.buys),date(trade.d))}${metric('Latest-week sells',cash(trade.sells),date(trade.last_d))}</div>${btn('Explore trading pulse','trading')}`:empty(), 'Confirmed USD executions; gross activity is not net flow.')}</div></div></div>`;}
 function pipelinePreview(){const os=(D.opportunities||[]).filter(o=>!o.IsClosed);return `<div class="wa-pair">${metric('Captured open opportunities',String(os.length),'Selected CRM sample')}${metric('Captured amount',cash(os.reduce((s,o)=>s+(Number(o.Amount)||0),0)),'Not a full-book pipeline total')}</div><div class="wa-deals">${os.slice(0,4).map(o=>`<button data-wa="customer" data-wa-id="${E(o.AccountId)}"><small>${E(o.StageName)}</small><strong>${E(o.Name)}</strong><b>${cash(o.Amount)}</b></button>`).join('')}</div>${btn('Open pipeline','page','pipeline')}`;}
 function planSource(p){return ['planSignals_reviewRowsSql','planSignals_atRiskRowsSql'].find(k=>rows(k).includes(p))||['planSignals_reviewRowsSql','planSignals_atRiskRowsSql'].find(k=>rows(k).some(r=>r.account_id===p.account_id&&r.next_review===p.next_review&&r.success===p.success));}
 function allPlans(){const m=new Map();for(const k of ['planSignals_reviewRowsSql','planSignals_atRiskRowsSql'])for(const p of rows(k))m.set(p.account_id,p);return [...m.values()];}
 function planRows(){return allPlans().filter(r=>C.planMode(r,ui.review,D.asOfDate));}
 function miniReviews(){const rs=planRows();return rs.length?rs.slice(0,4).map(r=>householdRow(r,planSource(r),`${date(r.next_review)} · ${pct(r.success)} success`)).join(''):empty('No rows in this bounded review capture match the selected lens.');}
 function reviewDetail(p){if(!p)return empty('Select a plan from the review worklist.');const id=p.account_id,detail=findRow('plan_details',id);return `<div class="wa-planfocus"><div class="wa-score" style="--wa-score:${Math.max(0,Math.min(100,Number(p.success)||0))}%"><span><b>${pct(p.success)}</b><small>modeled success</small></span></div><div><h2>${E(name(id))}</h2><p>${date(p.next_review)} · next provider review</p><div class="wa-pair">${metric('Plan goals',cash(p.goal_usd),'Provider goal total')}${metric('Goal count',num(p.goals,String),'Provider count')}</div><p>Last updated ${date(p.updated)} ${Number(p.stale)===1?'· stale under the native plan rule':''}</p><div class="wa-actions">${action(p,'meeting',planSource(p),'Propose review meeting')}${btn('Build review folio','folio',id)}</div></div></div>${detail?`<div class="wa-planassumptions">${metric('Source allocation',detail.allocation||'Unavailable','Provider recommendation')}${metric('Target retirement age',num(detail.retirement_age),'Planning assumption')}${metric('Monthly income target',cash(detail.monthly_income),'Plan target, not actual income')}</div>`:''}${goalCards(id)}<p class="wa-source">A planning success probability is a model output. It is distinct from actual goal funding and is not a guarantee.</p>`;}
 function calendar(rs,month,label){const selected=rs.find(p=>p.account_id===ui.selected)||rs[0];const dates=rs.map(r=>r.next_review).filter(Boolean).sort(),base=month?month+'-01':dates[0]||D.asOfDate;let d=new Date(base.slice(0,7)+'-01T12:00:00Z'),start=d.getUTCDay();return `<div class="wa-calendar"><header><strong>${d.toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})}</strong><small>${label||(month?'Recorded life events':'Provider review dates')}</small></header><div class="wa-days">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(s=>`<b>${s}</b>`).join('')}${Array.from({length:start},()=>'<span></span>').join('')}${Array.from({length:new Date(d.getUTCFullYear(),d.getUTCMonth()+1,0).getDate()},(_,i)=>{const dt=base.slice(0,7)+'-'+String(i+1).padStart(2,'0'),hits=rs.filter(r=>String(r.next_review).slice(0,10)===dt);return `<button data-wa="date" data-wa-id="${dt}" class="${hits.length?'has-review':''} ${selected?.next_review?.slice(0,10)===dt?'selected':''}" aria-label="${dt}, ${hits.length} captured reviews">${i+1}${hits.length?`<i>${hits.length}</i>`:''}</button>`;}).join('')}</div></div>`;}
 function reviews(){const s=one('planSignals_summarySql'),rs=planRows(),p=rs.find(r=>r.account_id===ui.selected)||rs[0];return `<div class="wa">${title('My review horizon','Plan health, review dates and the next commitment.')}<div class="wa-statstrip">${metric('Active / stale plans',num(s.plans),'Native aggregate; Draft excluded')}${metric('Below 70%',num(s.at_risk),'Plan attention')}${metric('Below 50%',num(s.critical),'Critical planning tier')}${metric('Due in 30 days',num(s.due30),'Provider review date')}${metric('Stale',num(s.stale),'Status or 12-month rule')}</div>${tabs([['due','Due in 30 days'],['risk','Plan attention'],['critical','Critical'],['stale','Stale'],['all','Captured plans']], 'review')}<div class="wa-reviewlayout"><div>${calendar(allPlans())}${panel('My review worklist',rs.filter(r=>!ui.day||String(r.next_review).slice(0,10)===ui.day).map(r=>householdRow(r,planSource(r),`${date(r.next_review)} · ${pct(r.success)} success`)).join('')||empty(), 'Select a household, then prepare the conversation.')}${ui.day?btn('Show all dates','clear-date'):''}</div>${panel('Selected plan',reviewDetail(p))}</div>${scope('planSignals_summarySql')}${scope('planSignals_atRiskRowsSql')}</div>`;}
 function title(h,p){return `<header class="wa-title"><div><p>My wealth workspace</p><h1>${E(h)}</h1><span>${E(p)}</span></div>${pill('Dated source capture')}</header>`;}
 function growth(){return `<div class="wa">${title('Capital, in context.','Find the next investment conversation, then keep the household and product together.')}${tabs([['coverage','Product opportunities'],['outside','Outside assets'],['acquisition','Acquisition']], 'capital')}${ui.capital==='coverage'?coverage():ui.capital==='outside'?outside():acquisition()}</div>`;}
 function coverage(){const os=offers(),ids=D.coverageIds?.length?D.coverageIds:[...new Set(os.map(o=>o.account))],id=ids.includes(ui.selected)?ui.selected:ids[0],o=selectedOffer(id);return `<div class="wa-statstrip">${metric('Households in this lens',String(ids.length),'Native up-to12 selection')}${metric('Open grid opportunities',num(D.gridOpen?.[0]?.n),'Independent CRM count')}${metric('Won in30days',num(D.gridWon?.[0]?.n),'Independent CRM count')}</div>${tabs([['cohort','Coverage'],['rising','Rising outside this view'],['falling','Falling outside this view']], 'movement')}${ui.movement&&ui.movement!=='cohort'?moverView(ui.movement):''}<div class="wa-capital-layout"><aside class="wa-panel"><h2>My household lens</h2><label class="wa-field">Find a household<input data-wa-search="households" value="${E(ui.q)}" placeholder="Search captured households"></label><div class="wa-households">${ids.filter(id=>name(id).toLowerCase().includes(ui.q.toLowerCase())).map(a=>`<button data-wa="select" data-wa-id="${E(a)}" class="${a===id?'selected':''}"><span class="wa-avatar">${E(api.initials(name(a)))}</span><span><strong>${E(name(a))}</strong><small>${offersForAccount(a).length} captured product scores</small></span></button>`).join('')}</div><p class="wa-source">${ids.length} captured households. Search is local to this source sample.</p></aside><div>${panel(name(id),`${capitalPath(id)}${productPicker(id)}${o?offerEvidence(o):empty()}`,'Exact household + product evidence')}${panel('Product coverage',`<div class="wa-productgrid">${(D.products||[]).map(p=>{const r=offersForAccount(id).find(o=>p.codes.includes(o.code)),isOwned=p.codes.some(c=>owned(id,c));return `<button data-wa="product" data-wa-id="${E(r?.code||'')}" ${!r||isOwned?'disabled':''}><span>${E(p.label)}</span><b>${isOwned?'✓ On file':r?pct(r.probability):'No scored row'}</b><small>${isOwned?'Existing product ownership':r?cash(r.value)+' modeled value':'Ownership may need review'}</small></button>`;}).join('')}</div>`,'Seven native Wealth product groups; score absence does not prove ownership.')}${scope('whitespace_offersSql')}</div></div>`;}
 function moverView(dir){const rs=rows(dir==='rising'?'whitespace_rising':'whitespace_falling').filter(r=>!D.coverageIds.includes(r.acct)).slice(0,25).filter(r=>!owned(r.acct,r.code));return panel(dir==='rising'?'Rising beyond the coverage lens':'Falling beyond the coverage lens',rs.map(r=>householdRow({...r,account_id:r.acct},dir==='rising'?'whitespace_rising':'whitespace_falling',`${offerLabel({code:r.code})} · ${cash(r.ev_moved)} expected-value change · ${Number(r.moved).toFixed(2)} conversion points`)).join('')||empty('No qualifying outside-cohort movers returned for this captured advisor book.'),'Native threshold: at least2 conversion points or$250 expected-value change. Cohort rows and known-owned products are excluded.');}
 function outside(){const total=one('home_heldAwayTotalSql'),rs=rows('home_heldAwaySql');return `<div class="wa-statstrip">${metric('Investable held away',cash(total.balance),'Active positive brokerage + robo')}${metric('Households',num(total.clients),'Independent source aggregate')}${rows('digitalLeakage_summarySql').map(r=>metric(r.kind||r.institution_type||'Digital assets',cash(r.balance),num(r.clients,String)+' households')).join('')}</div><div class="wa-two">${panel('Consolidation conversations',rs.map(r=>householdRow(r,'home_heldAwaySql',`${cash(r.balance)} · ${r.institution||''} · ${cash(r.net_flow)} monthly outside flow`)).join('')||empty(),'Monthly flow is external-account activity, not a transfer instruction.')}${panel('Digital platforms',rows('digitalLeakage_rowsSql').map(r=>householdRow(r,'digitalLeakage_rowsSql',`${r.kind||r.type||''} · ${cash(r.balance)} · ${r.institution||''}`)).join('')||empty(),'Crypto and robo evidence remains separate from investable consolidation totals.')}</div>${scope('home_heldAwaySql')}${scope('digitalLeakage_rowsSql')}`;}
 function acquisition(){const leads=D.leads||[];return `<div class="wa-two">${panel('My leads & referrals',btn('Create lead proposal','new-lead','','','primary')+leads.map(l=>`<article class="wa-lead"><div>${pill(l.Status||'Status not captured')}<h3>${E(l.Name||[l.FirstName,l.LastName].filter(Boolean).join(' '))}</h3><p>${E(l.Company||'Company not supplied')} · ${E(l.LeadSource||'Source not supplied')}</p></div>${btn('Review lead','lead',l.Id)}</article>`).join('')||empty('No Lead rows were returned in this capture.'),'CRM Leads are separate records from model candidates and graph introductions.')}${panel('Warm introductions',rows('relationshipGraph_warmIntroSql').map(r=>`<article class="wa-lead"><div><h3>${E(r.dst_name)}</h3><p>Introduced through ${E(name(r.src_id))}</p><small>${pct(r.conf)} graph confidence · discovered ${date(r.discovered)}</small></div>${btn('Review introduction','intro',r.dst_id)}</article>`).join('')||empty('Introduction source not available in this capture.'),'A graph edge does not establish consent or a completed referral.')}${panel('Business-owner conversations',rows('businessOwners_ownerRowsSql').map(r=>householdRow(r,'businessOwners_ownerRowsSql',Object.entries(r).filter(([k])=>!k.includes('id')).slice(0,3).map(([k,v])=>`${k}: ${v??'Unavailable'}`).join(' · '))).join('')||empty(),'Existing household relationships; confirm the source angle before proposing a handoff.')}${panel('Business-to-wealth connections',rows('businessOwners_handoffRowsSql').map(r=>`<article class="wa-handoff"><div><strong>${E(name(r.biz_id))}</strong><small>Business in my book</small></div><i>↔</i><div><strong>${E(r.owner_name)}</strong><small>${E(r.net_worth||'Wealth band not supplied')} · ${pct(r.conf)} graph confidence</small></div>${btn('Coordinate introduction','evidence',r.biz_id,'data-wa-source="businessOwners_handoffRowsSql"')}</article>`).join('')||empty(),'Source links identify an outside person and an owned business. Coordinate ownership before contact.')} ${panel('Emerging wealth',rows('wealthUpgrades_rowsSql').map(r=>householdRow(r,'wealthUpgrades_rowsSql',Object.entries(r).filter(([k])=>!k.includes('id')).slice(0,3).map(([k,v])=>`${k}: ${v??'Unavailable'}`).join(' · '))).join('')||empty(),'Source-qualified opportunities for an advisory conversation.')}</div>`;}
 function intelligence(){return `<div class="wa">${title('Know what changed.','Connect relationship signals, investment exposure and trading activity to the next conversation.')}${tabs([['care','Relationship signals'],['exposure','Position exposure'],['trading','Trading pulse']], 'intel')}${ui.intel==='exposure'?exposure():ui.intel==='trading'?trading():signals()}</div>`;}
 const feedSpecs={care:{key:'transactionSignals_callSentimentSql',title:'Conversation care',desc:'Negative and declining sentiment in the latest source week.',label:'Call sentiment'},aml:{key:'transactionSignals_amlChangeSql',title:'Screening changes',desc:'A dated change in risk rating needs review, not an inferred disposition.',label:'AML changes'},inflow:{key:'transactionSignals_largeInflowSql',title:'A liquidity conversation',desc:'A source transaction can prompt a conversation; confirm its origin and purpose.',label:'Large inflows'},liquidity:{key:'jobChangeSignals_liquidityRowsSql',title:'Career & liquidity moments',desc:'A detected career event is not proof of proceeds received.',label:'Career moments'},marketing:{key:'campaignTouches_campaignTouchSql',title:'Engagement to understand',desc:'Clicks and opens remain distinct from permission to contact or a completed sale.',label:'Marketing signals'}};
 function signalSummary(r,kind){if(kind==='aml')return `${r.prev_rating||'Unknown'} → ${r.risk_rating||'Unknown'} · screened ${date(r.screened)}`;if(kind==='care')return `${r.sentiment||'Sentiment not supplied'} · next call ${date(r.next_call)}`;if(kind==='inflow')return `${cents(r.amount)} · ${date(r.tx_date)}`;if(kind==='marketing')return `${r.clicks??'—'} clicks · ${r.product||'Product not supplied'}`;return `Detected ${date(r.detected_date__c)} · career source`;}
 function signals(){const spec=feedSpecs[ui.signal]||feedSpecs.aml,rs=rows(spec.key).map(r=>({...r,account_id:rowAccountKey(r,spec.key)})),r=rs.find(r=>r.account_id===ui.signalAccount)||rs[0],id=r?.account_id;return `<div class="wa-intelnav">${Object.entries(feedSpecs).map(([k,s])=>`<button data-wa="signal-lens" data-wa-id="${k}" class="${(ui.signal||'aml')===k?'selected':''}"><span>${E(s.label)}</span><b>${rows(s.key).length}</b><small>${source(s.key)?.status==='available'?'captured records':'unavailable'}</small></button>`).join('')}</div><div class="wa-intellayout"><div class="wa-panel"><h2>${E(spec.title)}</h2><p>${E(spec.desc)}</p><div class="wa-signalworklist">${rs.map(r=>`<button data-wa="signal-account" data-wa-id="${E(r.account_id)}" class="${id===r.account_id?'selected':''}"><span class="wa-avatar">${E(api.initials(name(r.account_id)))}</span><span><strong>${E(name(r.account_id))}</strong><small>${E(signalSummary(r,ui.signal||'aml'))}</small></span></button>`).join('')||empty(source(spec.key)?.status==='available'?'No matching source records returned for this advisor book.':'This signal source was not captured.')}</div>${scope(spec.key)}</div><section class="wa-signalstage">${r?`<div class="wa-signalidentity"><span class="wa-avatar">${E(api.initials(name(id)))}</span><div><p>My next conversation</p><h2>${E(name(id))}</h2></div></div>${ui.signal==='aml'?`<div class="wa-riskchange"><div><span>${r.change_type==='New'?'New screening':'Previous rating'}</span><strong>${E(r.prev_rating||'Not supplied')}</strong></div><i>→</i><div><span>Latest rating</span><strong>${E(r.risk_rating||'Unavailable')}</strong></div></div><p>${E(r.change_type||'Change type not supplied')} screening · screened ${date(r.screened)}</p><div class="wa-flags">${[['Sanctions',r.sanctions],['PEP',r.pep],['Adverse media',r.adverse_media]].map(([l,v])=>pill(l+': '+(v==null?'Not supplied':v===true||v==='true'?'Flagged':'No source hit'),v===true||v==='true'?'warn':'')).join('')}</div>`:ui.signal==='care'?`<div class="wa-conversationvisual"><span>Latest source sentiment</span><strong>${E(r.sentiment)}</strong><div class="wa-topics">${String(r.topics||'').split('|').filter(Boolean).map(t=>pill(t)).join('')}</div><div class="wa-pair">${metric('Deal-risk score',num(r.deal_risk,v=>Number(v).toFixed(1)),'Source score, not client health')}${metric('Next call on file',date(r.next_call),'Source call timing')}</div></div>`:ui.signal==='inflow'?`<div class="wa-inflowvisual"><span>Observed transaction</span><strong>${cents(r.amount)}</strong><p>${E(r.description||'Description not supplied')}</p><time>${date(r.tx_date)}</time></div>`:`<div class="wa-conversationvisual"><span>${E(spec.label)}</span><strong>${E(r.product||r.contact_name__c||'Review the dated source')}</strong><p>${E(signalSummary(r,ui.signal))}</p></div>`}<div class="wa-actions">${action(r,'task',spec.key,'Prepare conversation')}${btn('Inspect source','evidence',id,`data-wa-source="${spec.key}"`,'text-button')}</div><p class="wa-source">An observation helps me prepare. It does not establish consent, funds available, a compliance outcome or a completed action.</p>`:empty('There is no selected signal. Choose another source lens.')}</section></div>`;}
 function scoreHistory(o){const h=historyFor(o),vs=h.map(r=>Number(r.probability));if(!h.length)return empty('Monthly score history was not captured for this product.');const min=Math.floor(Math.min(...vs)),max=Math.ceil(Math.max(...vs)),span=Math.max(1,max-min),points=h.map((r,i)=>[h.length===1?180:25+i/(h.length-1)*310,102-(Number(r.probability)-min)/span*75]),path=points.map(p=>p.join(',')).join(' '),last=h.at(-1),move=C.number(last.scoremove),ev=C.number(last.valuemove);return `<div class="wa-scorehistory"><div><span>Actual monthly conversion scores</span><strong>${move==null?'':(move>0?'+':'')+move.toFixed(2)+' pts'} <small>over captured window</small></strong></div><svg viewBox="0 0 360 135" role="img" aria-label="Captured conversion score history, axis ${min} to ${max}%"><line x1="25" y1="102" x2="335" y2="102" stroke="#ddd4e9"/><text x="1" y="29">${max}%</text><text x="1" y="105">${min}%</text><polyline points="${path}" fill="none" stroke="#5548ad" stroke-width="3"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="${i===points.length-1?'#5548ad':'#fff'}" stroke="#5548ad"><title>${E(h[i].period)} · ${pct(h[i].probability)}</title></circle><text x="${x}" y="123" text-anchor="middle">${E(new Date(h[i].period+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'}))}</text>`).join('')}</svg><p>${ev==null?'Expected-value change unavailable':`${ev>=0?'+':'−'}${cash(Math.abs(ev))} modeled expected-value change`} · source-computed change, separate from the conversion-point change.</p></div>`;}

 function exposure(){const s=one('holdingsConcentration_summarySql'),rs=rows('holdingsConcentration_rowsSql'),ex=rows('holdingsConcentration_exposureSql'),max=Math.max(1,...ex.map(r=>Number(r.mv)));return `<div class="wa-statstrip">${metric('Holdings market value',cash(s.aum),'FinServ holding source only')}${metric('Households with holdings',num(s.clients),'Independent native aggregate')}${metric('Concentrated',num(s.concentrated),'Largest single stock ≥20%')}</div><div class="wa-two">${panel('Book exposure by ticker',`<div class="wa-exposures">${ex.map(r=>`<button data-wa="ticker" data-wa-id="${E(r.ticker)}"><span><strong>${E(r.ticker)}</strong><small>${E(r.name||'Issuer not supplied')}</small></span><i><b style="width:${Number(r.mv)/max*100}%"></b></i><span><strong>${cash(r.mv)}</strong><small>${num(r.holders,String)} holders</small></span></button>`).join('')}</div>`,'Native top-four single-stock exposures. Broad funds and sweeps are excluded.')}${panel('Position conversations',rs.map(r=>`<article class="wa-position">${householdRow(r,'holdingsConcentration_rowsSql',`${r.ticker} · ${pct(Number(r.w)*100)} of ${cash(r.tot)} holdings`)}<div class="wa-meter"><i style="width:${Math.min(100,Number(r.w)*100)}%"></i><b style="left:20%" title="20% concentration threshold"></b></div><small>${cash(r.mv)} position · ${Number(r.w)>=.2?'At / above':'Below'} threshold</small></article>`).join('')||empty(),'Weight uses that household’s holdings denominator. No price return, tax outcome or sale instruction is inferred.')}</div>${scope('holdingsConcentration_rowsSql')}`;}
 function trading(){const ws=rows('tradingPulse_weeklySql'),max=Math.max(1,...ws.flatMap(w=>[Number(w.buys),Number(w.sells)]));return `${panel('Nine-week trading pulse',`<div class="wa-tradechart" aria-label="Weekly gross buys and sells">${ws.map(w=>`<div><div><i class="buy" style="height:${Math.max(1,Number(w.buys)/max*150)}px" title="Buys ${cash(w.buys)}"></i><i class="sell" style="height:${Math.max(1,Number(w.sells)/max*150)}px" title="Sells ${cash(w.sells)}"></i></div><small>${E(String(w.d).slice(5,10))}</small><b>${num(w.n,String)}</b></div>`).join('')}</div><p class="wa-source">● Buy · ● Sell · numbers below each week are confirmed USD executions. Calendar weeks start Monday. Gross executions are not portfolio return or bank net flow.</p>`,'Actual weekly totals, rather than a household’s latest ten executions.')}${panel('Latest-week net sellers',rows('tradingPulse_sellersSql').map(r=>householdRow(r,'tradingPulse_sellersSql',`${cash(r.net_sold)} net sold · ${num(r.trades,String)} executions`)).join('')||empty(),'Conversation candidates; no trade-execution action is offered.')}${scope('tradingPulse_weeklySql')}`;}
 function goalCards(id){const gs=(D.goals||[]).filter(g=>g.FinancialPlan?.AccountId===id);return `<div class="wa-goals">${gs.length?gs.map(g=>{const target=C.number(g.TargetAmount),actual=C.number(g.ActualAmount);return `<article><div><small>${E(g.Type||'Goal type not supplied')}</small><h3>${E(g.Name)}</h3>${pill(g.Status||'Status not supplied')}</div><strong>${cash(actual)} <small>of ${cash(target)}</small></strong><div class="wa-meter"><i style="width:${target>0&&actual!=null?Math.min(100,actual/target*100):0}%"></i></div><p>Target ${date(g.TargetDate)} · ${E(g.Priority||'Priority not supplied')}</p>${btn('Review goal','goal',g.Id)}</article>`;}).join(''):empty('CRM goal details were not captured for this household. Provider goal totals remain a separate source.')}</div>`;}
 function deepRows(id,domain){const prefix=id==='001am00000qvjsAAAQ'?'julie':id==='001am000026ZtgKAAS'?'anika':null;return prefix&&source(prefix+'_'+domain)?rows(prefix+'_'+domain):Object.assign([],{unavailable:true});}
 function deepNote(id,domain){const prefix=id==='001am00000qvjsAAAQ'?'julie':id==='001am000026ZtgKAAS'?'anika':null;return prefix?scope(prefix+'_'+domain):'<p class="wa-source">This source domain was not captured for this exact household.</p>';}
 function readOnlyTable(cols,rs){return rs.unavailable?empty('This source domain was not captured for this exact household.'):rs.length?`<div class="wa-ledger">${rs.map(r=>`<article>${cols.map(([label,fn])=>`<div><small>${E(label)}</small><strong>${fn(r)}</strong></div>`).join('')}</article>`).join('')}</div>`:empty('No records returned for this captured household slice.');}
 function finances(id){const fa=holdings(id),trades=deepRows(id,'trades'),tx=deepRows(id,'transactions');return `<div class="wa">${panel('Financial accounts on file',readOnlyTable([['Account',r=>E(r.Name)],['Type',r=>E(r.FinServ__FinancialAccountType__c||'Not supplied')],['Balance',r=>cents(r.FinServ__Balance__c)],['Status',r=>E(r.FinServ__Status__c||'Not supplied')]],fa),'Financial-account balances include different product types. Their sum is not an investment AUM measure.')}${panel('Recent executions',readOnlyTable([['Executed',r=>date(r.dt)],['Side / instrument',r=>`${E(r.side)} · ${E(r.sym)}<small>${E(r.inst)}</small>`],['Shares × price',r=>`${num(r.qty,v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:6}))} × ${cents(r.px)}`],['Gross trade',r=>cents(r.tot)]],trades)+deepNote(id,'trades'),'Source executions are read-only. No order, sale recommendation or portfolio-return inference.')}${panel('Recent transactions',readOnlyTable([['Date',r=>date(r.dt)],['Category',r=>E(r.cat||'Not supplied')],['Type',r=>E(r.typ||'Not supplied')],['Amount',r=>cents(r.amt)]],tx)+deepNote(id,'transactions'),'Actual captured amounts keep cents. This bounded ledger does not establish a full cash-flow total.')}</div>`;}
 function profile(id){const a=account(id),prop=deepRows(id,'property')[0];return `<div class="wa">${panel('Household profile',`<h2>${E(a?.Name||name(id))}</h2><div class="wa-evidence">${[['Email',a?.PersonEmail],['Contact record',a?.PersonContactId],['Relationship record',a?.Id]].map(([k,v])=>`<div><span>${k}</span><strong>${E(v||'Not supplied')}</strong></div>`).join('')}</div><p class="wa-source">Household members, family roles and beneficiaries were not retrieved by the current-app source contract.</p>`)}${panel('Property context',prop?`<div class="wa-pair">${metric('Source ownership',prop.owner===true||prop.owner==='true'?'Owner':'Renter / non-owner',String(prop.q).slice(0,10))}${metric('Property type',prop.ptype||'Not supplied','Source observation')}</div>${prop.owner===true||prop.owner==='true'?`<div class="wa-pair">${metric('Estimated property value',cash(prop.val),'Provider estimate')}${metric('Estimated equity',cash(prop.eq),'Provider estimate')}</div>`:'<p>Value, equity and HELOC opportunity are withheld for a non-owner.</p>'}${deepNote(id,'property')}`:empty('Property evidence was not captured for this household.'))}</div>`;}
 function engagements(id){const a=account(id),activities=[...(D.tasks||[]),...(D.events||[])].filter(r=>r.WhatId===id||a?.PersonContactId&&r.WhoId===a.PersonContactId);return `<div class="wa">${panel('My commitments for this household',activities.slice(0,5).map(r=>`<article class="wa-workrow"><div><h3>${E(r.Subject)}</h3><small>${r.StartDateTime?when(r.StartDateTime):date(r.ActivityDate)} · ${E(r.Status||r.ShowAs||'Event')}</small></div>${btn('Review source','commitment',r.Id)}</article>`).join('')+btn('Open household workbench','account-work',id),'Source Task/Event records with exact WhatId or linked Contact WhoId; proposals remain separate.')}${panel('Service cases',((D.deepCases||[]).filter(r=>r.AccountId===id).slice(0,5).map(r=>`<article class="wa-workrow"><div><small>Case ${E(r.CaseNumber)} · ${E(r.Status)}</small><h3>${E(r.Subject)}</h3></div>${btn('Read source','case',r.Id)}</article>`).join('')||empty('No source case records returned for this captured household.')))}${panel('Conversations on file',`<div class="wa-timeline">${deepRows(id,'interactions').map(r=>`<article><time>${date(r.dt)}</time><div>${pill(r.purp||'Interaction')}<h3>${E(r.nm||'Source interaction')}</h3><p>${E(r.notes||'No meeting notes supplied.')}</p>${r.nxt?`<strong>Next step on file</strong><p>${E(r.nxt)}</p>`:''}</div></article>`).join('')||empty()}${deepNote(id,'interactions')}</div>`,'Dated source interaction notes, separate from private preparation.')}${panel('Campaign history',readOnlyTable([['When',r=>date(r.dt)],['Campaign',r=>E(r.nm)],['Product',r=>E(r.prod||'Not supplied')],['Action',r=>E(r.act||'Not supplied')]],deepRows(id,'campaigns'))+deepNote(id,'campaigns'),'Campaign activity is not proof of consent, conversion or funds received.')}</div>`;}
 function allExternalAssets(id){const key='customer_allAssets_'+id,s=source(key),r=rows(key)[0];if(!s)return '';const value=r?.total==null?(Number(r?.institutions)===0?'No qualifying rows':'Unavailable'):cents(r.total);return `<div class="wa wa-all-assets">${panel('All active external assets',`<div class="wa-pair">${metric('All asset categories',value,"Latest active Plaid rows with Balance_Category = asset")}${metric('Distinct institutions',r?.distinct_institutions==null?'Unavailable':String(r.distinct_institutions),String(r?.institutions??'—')+' qualifying asset records')}</div><p class="wa-source">Captured ${E(s.capturedAt||D.capturedAt)}${r?.period?' · source period '+date(r.period):' · no qualifying rows in the latest-period query'}. This customer-summary filter is separate from positive Brokerage/Robo investment opportunities. The totals must not be substituted for one another.</p>`,'The broader customer summary stays distinct from investment-conversation eligibility.')}</div>`;}
 function capturedSignals(id,kinds=Object.keys(feedSpecs)){const matches=kinds.flatMap(kind=>{const spec=feedSpecs[kind];return rows(spec.key).filter(r=>rowAccountKey(r,spec.key)===id).map(r=>({kind,spec,r}));});if(!matches.length)return '';return `<div class="wa">${panel('Captured relationship signals',`<div class="wa-linked-signals">${matches.map(({kind,spec,r})=>`<article data-wa-linked-source="${E(spec.key)}"><h3>${E(spec.label)}</h3><p>${E(signalSummary(r,kind))}</p>${kind==='aml'?`<div class="wa-flags">${[['Sanctions',r.sanctions],['PEP',r.pep],['Adverse media',r.adverse_media]].map(([label,v])=>pill(label+': '+(v==null?'Not supplied':v===true||v==='true'?'Flagged':'No source hit'),v===true||v==='true'?'warn':'')).join('')}</div>`:''}<div class="wa-actions">${btn('Inspect source','evidence',id,`data-wa-source="${E(spec.key)}"`)}${btn('Prepare conversation','propose',id,`data-wa-source="${E(spec.key)}" data-wa-kind="task"`)}</div>${scope(spec.key)}</article>`).join('')}</div>`,'The same dated source evidence used in Intelligence, scoped to this exact household.')}</div>`;}
 function screening(id){const r=deepRows(id,'screening')[0];if(!r&&findRow('transactionSignals_amlChangeSql',id))return `<div class="wa">${capturedSignals(id,['aml'])}</div>`;return `<div class="wa">${panel('Dated screening evidence',r?`<div class="wa-riskchange"><div><span>Source risk rating</span><strong>${E(r.rating||'Not supplied')}</strong></div><div><span>Screened</span><strong>${date(r.dt)}</strong></div></div><div class="wa-flags">${[['Sanctions',r.sanc],['PEP',r.pep],['Adverse media',r.media]].map(([l,v])=>pill(l+': '+(v==null?'Not supplied':v===true||v==='true'?'Flagged':'No source hit'),v===true||v==='true'?'warn':'')).join('')}</div>${deepNote(id,'screening')}`:empty('Screening evidence was not captured for this household.'),'A provider observation is not a completed compliance disposition. No inferred KYC status.')}</div>`;}
 function notebook(id){return `<div class="wa">${folio(id)}${panel('Source notes',`<div class="wa-timeline">${deepRows(id,'notes').map(r=>`<article><time>${date(r.dt)}</time><div><h3>${E(r.ttl)}</h3><p>${E(r.notes)}</p></div></article>`).join('')||empty('No source notes returned for this household.')}</div>${deepNote(id,'notes')}`,'Source notes are read-only; private folio questions stay in this browser.')}</div>`;}
 function newGoal(accountId=state.client||''){const plans=(D.financialPlans||[]).filter(p=>!accountId||p.AccountId===accountId);if(!plans.length){modal('Create goal proposal',empty('No permitted financial-plan records were captured for this household. A provider plan is separate from the CRM financial plan required for a goal.'));return;}modal('Create goal proposal',`<div class="wa"><form id="wa-new-goal"><p class="wa-source">A local proposal; choose the exact financial plan before entering the goal.</p><label class="wa-field">Financial plan<select name="financialPlanId" required><option value="">Choose the exact financial plan…</option>${plans.map(p=>`<option value="${E(p.Id)}">${E(name(p.AccountId))} · ${E(p.Name)}</option>`).join('')}</select></label>${field('Goal name','title','')}${field('Goal type','goalType','')}${field('Status','status','IN_PROGRESS')}${field('Priority','priority','')}${field('Target date','dueDate','','date')}${field('Target amount (USD)','targetAmount','','number')}${field('Actual amount (USD)','actualAmount','','number')}<label class="wa-field">Description<textarea name="description"></textarea></label><button class="primary">Save local goal proposal</button></form></div>`);document.getElementById('wa-new-goal').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget)),plan=plans.find(p=>p.Id===values.financialPlanId);if(!plan)return;api.saveDraft('goal',{...values,accountId:plan.AccountId,sourceAccountId:plan.AccountId,sourceKind:'FinancialPlan',sourceKey:plan.Id,operation:'create-proposal'});document.getElementById('record-dialog').close();});}
 function editLocal(d){
  const byKind={
   lead:[['First name','firstName'],['Last name','lastName'],['Company','company'],['Email','email'],['Status','status'],['Lead source','leadSource'],['Annual company revenue (USD)','annualRevenue']],
   goal:[['Goal name','title'],['Goal type','goalType'],['Priority','priority'],['Status','status'],['Target amount (USD)','targetAmount'],['Actual amount (USD)','actualAmount'],['Target date','dueDate']],
   task:[['Task title','title'],['Status','status'],['Priority','priority'],['Activity type','type'],['Due date','dueDate']],
   meeting:[['Meeting title','title'],['Start (local time)','start'],['Planning time zone','timeZone'],['Location','location'],['Show as','showAs'],...(d.sourceRecordId?[['Activity type','type'],['Assigned owner ID','ownerId']]:[['Duration (minutes)','duration']])],
   opportunity:[['Opportunity name','title'],['Amount (USD)','amount'],['Stage','stage'],['Close date','date']],
   email:[['Recipient email','email'],['Subject','title']],
   case:[['Case subject','title'],['Priority','priority'],['Status','status']],
   life:[['Event name','title'],['Event date','date']]
  },fields=byKind[d.kind]||[['Title','title']],fixedRelationship=d.kind==='goal'||d.kind==='life';
  modal('Edit my local proposal',`<div class="wa"><form id="wa-edit-local">${d.contextReviewRequired?'<p class="wa-source">The relationship changed. Source associations were cleared; review every authored field for the newly selected relationship.</p>':''}${d.kind==='lead'?'':`<label class="wa-field">Exact relationship<select name="accountId" ${fixedRelationship?'disabled':''}><option value="" ${!d.accountId?'selected':''}>No Account link</option>${d.accountId&&!accounts().some(a=>a.Id===d.accountId)?`<option value="${E(d.accountId)}" selected>Saved related record · ${E(d.accountId)} (not in this household capture)</option>`:''}${accounts().map(a=>`<option value="${E(a.Id)}" ${a.Id===d.accountId?'selected':''}>${E(a.Name)} · …${E(a.Id.slice(-5))}</option>`).join('')}</select></label>`}${fields.map(([l,k])=>field(l,k,k==='start'?(d.start||d.date):k==='dueDate'?(d.dueDate||d.date):d[k],k==='email'?'email':['amount','targetAmount','actualAmount','annualRevenue','duration'].includes(k)?'number':k==='start'?'datetime-local':['date','dueDate'].includes(k)?'date':'text')).join('')}${d.kind==='email'?`<label class="wa-field">Email body<textarea name="body">${E(d.body||'')}</textarea></label>`:''}<label class="wa-field">${d.kind==='email'?'Internal notes':'Notes / description'}<textarea name="description">${E(d.description||d.notes||'')}</textarea></label>${d.financialPlanId?`<p class="wa-source">The original financial plan stays linked to this goal. Changing a goal’s plan is not supported.</p>`:''}${d.kind==='life'?`<p class="wa-source">The recorded Contact and event type stay fixed. Only the name and date are editable.</p>`:''}${d.sourceRecordId?`<p class="wa-source">Original source activity stays linked. WhoId${d.kind==='meeting'?' and Event duration remain':' remains'} fixed.</p>`:''}${d.contextReviewRequired?'<label class="wa-field"><span><input type="checkbox" name="contextReviewConfirmed"> I reviewed this text for the selected relationship</span></label>':''}<button class="primary">Save local edits</button></form></div>`);
  document.getElementById('wa-edit-local').addEventListener('submit',e=>{e.preventDefault();const patch=Object.fromEntries(new FormData(e.currentTarget));if(d.sourceRecordId&&['task','meeting'].includes(d.kind)&&'accountId' in patch&&(patch.accountId||'')!==(d.accountId||'')){patch.whatId=patch.accountId||null;patch.contextReviewRequired=true;}if(patch.contextReviewConfirmed){patch.contextReviewRequired=false;delete patch.contextReviewConfirmed;}if(d.notes!=null)patch.notes=patch.description;if(d.kind==='meeting'&&patch.start){const proposed=new Date(patch.start);if(!Number.isNaN(proposed.getTime()))patch.proposedStartUtc=proposed.toISOString();}api.updateDraft(d.id,patch);document.getElementById('record-dialog').close();});return true;
 }

 function relationship(tab,a,fallback){if(!active())return null;syncRouteView();const id=a.Id;if(!accounts().some(a=>a.Id===id))return `<div class="wa">${empty('A dedicated Wealth source capture is unavailable for this relationship. Select a verified household from My relationships.')}</div>`;if(tab==='growth')return `<div class="wa">${panel('Household opportunities',`${capitalPath(id)}${productPicker(id)}${selectedOffer(id)?offerEvidence(selectedOffer(id)):empty('Product evidence is unavailable for this household.')}`)}</div>`;if(tab==='journey')return `<div class="wa">${panel('Plans & goals',btn('Create goal proposal','new-goal',id,'','primary')+goalCards(id))+panel('Contact-linked milestones',btn('Log life event','new-life',id)+milestones(id))}${panel('Provider plan',reviewDetail(allPlans().find(p=>p.account_id===id)))}</div>`;if(tab==='tools')return `<div class="wa">${folio(id)}</div>`;if(tab==='profile')return profile(id);if(tab==='finances')return finances(id)+allExternalAssets(id)+capturedSignals(id,['inflow','liquidity']);if(tab==='engagement')return engagements(id)+capturedSignals(id,['care','marketing']);if(tab==='screening')return screening(id);if(tab==='notebook')return notebook(id);if(tab==='overview'){const p=allPlans().find(p=>p.account_id===id),actualPlan=rows('deep_plans').find(p=>p.account_id===id);return `<div class="wa">${panel('My household brief',`<h2>${E(a.Name)}</h2><div class="wa-actions">${btn('Build review folio','folio',id,'','primary')}${btn('Plan follow-up','quick-task',id)}</div>${p?reviewDetail(p):actualPlan?`<div class="wa-pair">${metric('Provider plan status',actualPlan.status,'Latest captured plan')}${metric('Modeled success',pct(actualPlan.success),'Draft excluded from review priorities')}</div><p>${E(actualPlan.allocation||'Allocation not supplied')} · target retirement age ${E(actualPlan.retirement_age??'not supplied')}</p>`:empty('No plan-health row in this bounded capture. This does not mean no plan exists.')}<div class="wa-pair">${metric('Financial accounts captured',String(holdings(id).length),'Different product types; not AUM')}${metric('Product scores captured',String(offersForAccount(id).length),'Modeled eligibility')}</div>`)}${capturedSignals(id)}${goalCards(id)}</div>`;}return null;}
 function folio(id){const a=account(id),key=`wealth.folio.${owner}.${id}`,saved=api.read(key,{sections:['Plan','Goals','Products'],questions:''}),sections=new Set(saved.sections),plans=[...rows('plan_details'),...rows('deep_plans')].filter(p=>p.account_id===id),p=plans[0],notes=deepRows(id,'notes'),interactions=deepRows(id,'interactions');return panel('My review folio',`<h2>${E(a?.Name||name(id))}</h2><p>Choose what belongs in the next conversation. This working folio stays private in this browser.</p><div class="wa-foliolayout"><div><div class="wa-checks">${['Plan','Goals','Products','Interactions','Source notes'].map(s=>`<label><input type="checkbox" data-wa-section="${E(s)}" ${sections.has(s)?'checked':''}>${E(s)}</label>`).join('')}</div><label class="wa-field">Questions for my review<textarea id="wa-folio-questions" rows="5">${E(saved.questions||'')}</textarea></label>${btn('Save private folio','save-folio',id,'','primary')}${btn('Propose next meeting','quick-meeting',id)}</div><div class="wa-paper"><span>Review working paper · ${E(D.capturedAt)}</span><h3>${E(a?.Name||name(id))}</h3>${sections.has('Plan')?`<h4>Plan context</h4>${p?`<p>${E(p.status)} plan · ${pct(p.success)} modeled success · ${cash(p.goal_usd)} provider goal exposure</p><p>Next provider review ${date(p.next_review)} · ${E(p.allocation||'Allocation not supplied')}</p>`:'<p>No provider plan details captured for this household.</p>'}`:''}${sections.has('Goals')?`<h4>CRM goals</h4>${(D.goals||[]).filter(g=>g.FinancialPlan?.AccountId===id).map(g=>`<p>${E(g.Name)} · ${cents(g.ActualAmount)} of ${cents(g.TargetAmount)} · ${E(g.Status||'Status not supplied')}</p>`).join('')||'<p>No CRM goals were captured for this household.</p>'}`:''}${sections.has('Products')?`<h4>Product conversations</h4>${offersForAccount(id).filter(o=>o.rank!=null&&!owned(id,o.code)).map(o=>`<p>${E(offerLabel(o))} · ${pct(o.probability)} modeled conversion · ${cash(o.value)} modeled expected value</p>`).join('')||'<p>No eligible unowned product rows in this capture.</p>'}`:''}${sections.has('Interactions')?`<h4>Recent source interaction</h4>${interactions.slice(0,1).map(n=>`<strong>${E(n.nm)}</strong><p>${E(n.notes||'No notes supplied')}</p><small>${date(n.dt)}</small>`).join('')||'<p>No source interactions captured for this household.</p>'}`:''}${sections.has('Source notes')?`<h4>Source notes</h4>${notes.slice(0,1).map(n=>`<p>${E(n.ttl)} · ${date(n.dt)}</p><p>${E(n.notes)}</p>`).join('')||'<p>No source notes returned for this household.</p>'}`:''}${saved.questions?`<h4>My private questions</h4><p>${E(saved.questions)}</p>`:''}</div></div><p class="wa-source">This working copy uses captured source records. Saving keeps it in this browser; no packet has been sent or saved to the client record.</p>`);}

 function sourceCommitments(kind){return (kind==='meetings'?D.events:D.tasks)||[];}
 function commitmentSummary(r){const event=!!r.StartDateTime;return `<div class="wa-commitmentfocus"><div class="wa-dateblock"><b>${r.StartDateTime||r.ActivityDate?new Date(r.StartDateTime||r.ActivityDate).getUTCDate():'—'}</b><span>${event?'Event':'Task'}</span></div><h3>${E(r.Subject)}</h3><p>${r.StartDateTime?when(r.StartDateTime):date(r.ActivityDate)} · ${E(r.Status||r.ShowAs||'Source activity')}</p><p>${E(r.Description||'No description supplied.')}</p><div class="wa-assignment"><small>Assigned to</small><strong>${r.OwnerId===owner?E(D.ownerName):'Source owner record'}</strong><small>Related record</small><strong>${E(name(r.WhatId))}</strong><small>Attendee / person link</small><strong>${E(r.WhoId||'Not supplied')}</strong></div>${btn('Review supported edits','commitment',r.Id,'','primary')}<p class="wa-source">Source Who, What and Owner remain distinct. Proposed edits do not update the CRM activity.</p></div>`;}
 function work(fallback){const months=[...new Set((D.events||[]).filter(e=>!ui.workAccount||e.WhatId===ui.workAccount||e.WhoId===account(ui.workAccount)?.PersonContactId).map(e=>String(e.StartDateTime).slice(0,7)))].sort();if(!months.includes(ui.workMonth))ui.workMonth=months.at(-1)||D.asOfDate.slice(0,7);if(state.sub==='drafts'&&ui.work!=='drafts'){ui.work='drafts';api.write(viewStorageKey,ui);}const kind=state.sub==='drafts'?'drafts':ui.work||'tasks',all=sourceCommitments(kind),rs=all.filter(r=>!ui.workAccount||r.WhatId===ui.workAccount||r.WhoId===account(ui.workAccount)?.PersonContactId).filter(r=>kind!=='meetings'||ui.wq||String(r.StartDateTime).startsWith(ui.workMonth)).filter(r=>!ui.wq||[r.Subject,r.Description,r.Status].some(v=>String(v||'').toLowerCase().includes(ui.wq.toLowerCase()))).filter(r=>!ui.day||String(r.StartDateTime||r.ActivityDate||'').slice(0,10)===ui.day),r=rs.find(r=>r.Id===ui.commitment)||rs[0],drafts=api.getDrafts().filter(d=>d.persona==='wealth');return `<div class="wa">${title('My execution desk','Commitments on file, a prepared review, and the next action I propose.')}${tabs([['tasks','Tasks on file'],['meetings','Meetings on file'],['cases','Service cases'],['drafts','My local proposals']], 'work')}${kind==='drafts'?panel('My local proposals',`<div class="wa-draftgrid">${drafts.map(d=>`<article>${pill(d.operation||'create-proposal')}<small>${E(d.kind)}</small><h3>${E(d.title)}</h3><p>${d.accountId?E(name(d.accountId)):E(d.company||'Lead proposal')}</p>${d.offerCode?`<p>Product: ${E(d.offerCode)}</p>`:''}${d.sourceKind?`<p class="wa-source">Linked ${E(({product:'product',FinancialPlan:'financial plan',goal:'goal',Task:'recorded task',Event:'recorded meeting',planSignals_atRiskRowsSql:'planning',planSignals_reviewRowsSql:'review',transactionSignals_amlChangeSql:'screening',transactionSignals_callSentimentSql:'conversation',relationshipGraph_warmIntroSql:'introduction',businessOwners_handoffRowsSql:'business relationship'})[d.sourceKind]||'source')} evidence retained.</p>`:''}${d.contextReviewRequired?pill('Review changed relationship','warn'):''}${btn('Edit local proposal','edit-local',d.id)}</article>`).join('')||empty('Prepare a conversation or propose an action. It will stay here until you choose to review it.')}</div>`,'Private proposals are not completed writes, sent messages or booked meetings.'):kind==='cases'?panel('Service cases on file',`<div class="wa-casegrid">${(D.deepCases||[]).slice(0,8).map(c=>`<article>${pill(c.Priority||'Priority not supplied',c.Priority==='High'?'warn':'')}<small>Case ${E(c.CaseNumber)}</small><h3>${E(c.Subject)}</h3><p>${E(name(c.AccountId))}</p><strong>${E(c.Status)}</strong><p>${date(c.CreatedDate)}</p>${btn('Read source case','case',c.Id)}</article>`).join('')||empty()}</div><p class="wa-source">Selected cases for the two deep households; not a book-level service-case count.</p>`):`<div class="wa-worklayout"><div>${panel(kind==='meetings'?'My meeting calendar':'My task focus',`${ui.workAccount?`<p>${pill(name(ui.workAccount))}${btn('Show all captured commitments','clear-work-account','','','text-button')}</p>`:''}${kind==='meetings'?`<label class="wa-field">Calendar month<select data-wa-workmonth>${[...new Set((D.events||[]).map(e=>String(e.StartDateTime).slice(0,7)))].sort().map(m=>`<option value="${m}" ${m===ui.workMonth?'selected':''}>${E(new Date(m+'-01T12:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'}))}</option>`).join('')}</select></label>`:''}${kind==='meetings'?calendar((D.events||[]).map(e=>({account_id:e.WhatId,next_review:String(e.StartDateTime).slice(0,10)})),ui.workMonth,'Recorded CRM Events'):`<div class="wa-tasklanes">${['Not Started','In Progress','Completed'].map(status=>`<div><b>${all.filter(t=>t.Status===status).length}</b><span>${status}</span></div>`).join('')}</div>`}<label class="wa-field">Find a source commitment<input data-wa-worksearch value="${E(ui.wq||'')}" placeholder="Search title, description or status"></label><div class="wa-commitmentlist">${rs.slice(0,8).map(r=>`<button data-wa="choose-commitment" data-wa-id="${E(r.Id)}" class="${r.Id===ui.commitment?'selected':''}"><span>${date(r.StartDateTime||r.ActivityDate)}</span><strong>${E(r.Subject)}</strong><small>${E(r.Status||r.ShowAs||'Source Event')}</small></button>`).join('')||empty('No captured commitments match this search or day.')}</div>${ui.day?btn('Show all dates','clear-date'):''}<p class="wa-source">${rs.length} matches in a bounded source sample. Showing the first8; refine the search to find a specific commitment.</p>`)}</div>${panel(r?'Selected commitment':'No matching commitment',r?commitmentSummary(r):empty(),'Review source context before proposing changes.')}</div>`}</div>`;}

 function evidence(key,id){const r=findRow(key,id);if(!r){modal('Source unavailable',empty('This exact source record is not in the capture.'));return;}modal(name(id)+' · source evidence',`<div class="wa"><div class="wa-evidence">${Object.entries(r).map(([k,v])=>`<div><span>${E(k.replaceAll('_',' '))}</span><strong>${v==null?'Unavailable':E(typeof v==='object'?JSON.stringify(v):String(v))}</strong></div>`).join('')}</div>${scope(key)}<div class="wa-actions">${action(r,'task',key)}</div></div>`);}
 document.addEventListener('input',e=>{if(!active())return;if(e.target.hasAttribute('data-wa-worksearch')){ui.wq=e.target.value;const pos=e.target.selectionStart;render(true);const n=document.querySelector('[data-wa-worksearch]');n?.focus();n?.setSelectionRange(pos,pos);return;}if(e.target.hasAttribute('data-wa-directory')){state.q=e.target.value;ui.q=e.target.value;const pos=e.target.selectionStart;render(true);const n=document.querySelector('[data-wa-directory]');n?.focus();n?.setSelectionRange(pos,pos);return;}if(!e.target.dataset.waSearch)return;ui.q=e.target.value;const pos=e.target.selectionStart;render(true);const n=document.querySelector('[data-wa-search]');n?.focus();n?.setSelectionRange(pos,pos);});
 document.addEventListener('change',e=>{if(!active())return;if(e.target.hasAttribute('data-wa-workmonth')){ui.workMonth=e.target.value;ui.day=null;render();return;}if(e.target.hasAttribute('data-wa-month')){ui.month=e.target.value;render();return;}if(!e.target.dataset.waSelect)return;ui.product=e.target.value;render();});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-wa]');if(!b||!active())return;const act=b.dataset.wa,id=b.dataset.waId,key=b.dataset.waSource;
 if(act==='signal-lens'){ui.signal=id;ui.signalAccount=null;render();}
 if(act==='signal-account'){ui.signalAccount=id;render();}
 if(act==='tab'){ui[b.dataset.waKey]=b.dataset.waValue;if(b.dataset.waKey==='work')state.sub=b.dataset.waValue;ui.day=null;ui.wq='';render();}
 if(act==='select'){ui.selected=id;render();}
 if(act==='date'){ui.day=id;ui.selected=allPlans().find(p=>String(p.next_review).slice(0,10)===id)?.account_id;render();}
 if(act==='account-work'){ui.workAccount=id;ui.work='tasks';state.sub='tasks';ui.day=null;api.write(viewStorageKey,ui);navigate({page:'work'});}
 if(act==='clear-work-account'){ui.workAccount=null;render();}
 if(act==='choose-commitment'){ui.commitment=id;render();}
 if(act==='case'){const r=(D.deepCases||[]).find(r=>r.Id===id);if(r)modal('Case '+r.CaseNumber,`<div class="wa"><h2>${E(r.Subject)}</h2><p>${E(r.Status)} · ${E(r.Priority)}</p><p>${E(name(r.AccountId))} · opened ${date(r.CreatedDate)}</p><p class="wa-source">Read-only source case. No resolution, disposition or update is implied.</p></div>`);}
 if(act==='clear-date'){ui.day=null;render();}
 if(act==='page')navigate({page:id});
 if(act==='customer'){document.getElementById('record-dialog')?.close();navigate({page:'relationships',client:id,tab:'overview'});}
 if(act==='trading'){ui.intel='trading';navigate({page:'intelligence'});}
 if(act==='evidence')evidence(key,id);
 if(act==='product'&&id){ui.product=id;render();}
 if(act==='ticker'){const rs=rows('holdingsConcentration_rowsSql').filter(r=>r.ticker===id);modal(id+' · captured holders',`<div class="wa">${rs.map(r=>householdRow(r,'holdingsConcentration_rowsSql',`${pct(Number(r.w)*100)} · ${cash(r.mv)}`)).join('')||empty('The bounded top-position worklist has no matching holder rows. The exposure aggregate includes additional holdings.')}</div>`);}
 if(act==='propose'){const r=findRow(key,id);if(r)api.openBaseForm(b.dataset.waKind||'task',name(id),null,{...provenance(key,r),title:(b.dataset.waKind==='meeting'?'Review plan with ':'Discuss source evidence with ')+name(id)});}
 if(act==='offer-task'||act==='offer-opportunity'){const o=offersForAccount(id).find(o=>o.code===b.dataset.waCode);if(o&&act==='offer-opportunity'&&(owned(id,o.code)||o.rank==null||existingOpportunity(o))){api.toast?.('Review current ownership and the existing grid opportunity before creating another proposal.');return;}if(o)api.openBaseForm(act==='offer-task'?'task':'opportunity',name(id),null,{accountId:id,offerAccountId:id,offerCode:o.code,sourceAccountId:id,sourceKind:'product',sourceKey:`${id}:${o.code}:${o.period}`,crossSell:act==='offer-opportunity',title:offerLabel(o)+' — '+name(id),notes:`${pct(o.probability)} modeled conversion; ${cash(o.value)} modeled expected value. Confirm ownership, suitability and proposed amount. Source ${o.period}.`});}
 if(act==='folio')modal('My review folio',`<div class="wa">${folio(id)}</div>`);
 if(act==='save-folio'){api.write(`wealth.folio.${owner}.${id}`,{sections:[...document.querySelectorAll('[data-wa-section]:checked')].map(e=>e.dataset.waSection),questions:document.getElementById('wa-folio-questions')?.value||''});api.toast?.('Private review folio saved in this browser.');if(document.getElementById('record-dialog')?.open)modal('My review folio',`<div class="wa">${folio(id)}</div>`);else render();}
 if(act==='quick-task'||act==='quick-meeting')api.openBaseForm(act==='quick-task'?'task':'meeting',name(id),null,{accountId:id,title:(act==='quick-task'?'Follow up with ':'Review with ')+name(id)});
 if(act==='life-edit'){const r=workspaceCapture.personas.wealth.lifeEvents.find(r=>r.Id===id);if(r)lifeForm(r);}
 if(act==='new-life')newLife(id||state.client||'');
 if(act==='new-goal')newGoal(id||state.client||'');
 if(act==='new-lead')leadForm({});
 if(act==='edit-local'){const d=api.getDrafts().find(d=>d.id===id&&d.persona==='wealth');if(d)editLocal(d);}
 if(act==='goal'){const g=(D.goals||[]).find(g=>g.Id===id);if(g)goalForm(g);}
 if(act==='lead'){const l=(D.leads||[]).find(l=>l.Id===id);if(l)leadForm(l);}
 if(act==='commitment'){const r=[...(D.tasks||[]),...(D.events||[])].find(r=>r.Id===id);if(r)commitment(r);}
 if(act==='intro'){const r=rows('relationshipGraph_warmIntroSql').find(r=>r.dst_id===id);if(r)modal('Introduction · '+r.dst_name,`<div class="wa"><p>Referral edge from ${E(name(r.src_id))} · ${pct(r.conf)} confidence · discovered ${date(r.discovered)}.</p><p>Target ownership: ${Number(r.dst_owned)?'An owner is on file; coordinate before contact.':'No owner in the captured graph.'}</p>${btn('Prepare introduction request','propose',r.src_id,'data-wa-source="relationshipGraph_warmIntroSql"','primary')}<p class="wa-source">Graph targets remain separate from CRM Lead records. No consent or handoff is claimed.</p></div>`);}
 });
 function field(label,name,value,type='text',extra=''){return `<label class="wa-field">${E(label)}<input name="${E(name)}" type="${type}" value="${E(value??'')}" ${extra} ${['title','lastName','company','targetAmount'].includes(name)?'required':''}></label>`;}
 function proposalForm(kind,title,record,fields,meta){modal(title,`<div class="wa"><form id="wa-proposal"><p class="wa-source">Save a local ${kind} proposal for review. The source record remains unchanged.</p>${fields}<button class="primary" type="submit">Save local proposal</button></form></div>`);document.getElementById('wa-proposal').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(kind==='meeting'&&data.start){const d=new Date(data.start);if(!Number.isNaN(d.getTime()))data.proposedStartUtc=d.toISOString();}api.saveDraft(kind,{...meta,...data,persona:'wealth',sourceRecordId:record.Id,name:title,operation:record.Id?'update-proposal':'create-proposal'});document.getElementById('record-dialog').close();api.toast?.('Local proposal saved.');render();});}
 function milestones(id){const rs=workspaceCapture.personas.wealth.lifeEvents.filter(e=>e.PrimaryPerson?.AccountId===id);return rs.length?`<div class="wa-commitments">${rs.map(e=>`<article><div><h3>${E(e.Name)}</h3><p>${E(e.EventType)} · ${date(e.EventDate)}</p><small>${E(e.PrimaryPerson?.Name||'Captured Contact')}</small></div>${btn('Review life event','life-edit',e.Id)}</article>`).join('')}</div>`:empty('No Contact-linked milestones were captured for this household.');}
 function lifeForm(e){proposalForm('life','Review life event · '+e.Name,e,field('Event name','title',e.Name)+field('Event date','date',String(e.EventDate||'').slice(0,10),'date','required')+`<p class="wa-source">The original Contact and event type (${E(e.EventType)}) stay fixed.</p>`,{accountId:e.PrimaryPerson?.AccountId,primaryPersonId:e.PrimaryPersonId||e.PrimaryPerson?.Id,eventType:e.EventType,sourceAccountId:e.PrimaryPerson?.AccountId,sourceKind:'PersonLifeEvent',sourceKey:e.Id});}
 function newLife(accountId=''){const contacts=new Map();for(const a of accounts())if(a.PersonContactId)contacts.set(a.PersonContactId,{id:a.PersonContactId,name:a.Name,accountId:a.Id});for(const e of workspaceCapture.personas.wealth.lifeEvents||[]){const p=e.PrimaryPerson;if(p?.Id&&account(p.AccountId))contacts.set(p.Id,{id:p.Id,name:p.Name||name(p.AccountId),accountId:p.AccountId});}const choices=[...contacts.values()].filter(p=>!accountId||p.accountId===accountId);if(!choices.length){modal('Log life event',empty('No exact Contact was captured for this household. A typed name cannot establish the person link.'));return;}modal('Log life event',`<div class="wa"><form id="wa-new-life"><label class="wa-field">Contact<select name="primaryPersonId" required><option value="">Choose the exact Contact…</option>${choices.map(p=>`<option value="${E(p.id)}">${E(p.name)} · ${E(p.id.slice(-6))}</option>`).join('')}</select></label>${field('Event name','title','')}<label class="wa-field">Event type<select name="eventType">${['Birth','Baby','Graduation','Job','Marriage','Relocation','Home','Car','Diagnosis','Retirement'].map(t=>`<option>${t}</option>`).join('')}</select></label>${field('Event date','date','','date','required')}<button class="primary">Keep local life-event proposal</button><p class="wa-source">Contact/type are set at creation. This proposal does not insert a Salesforce record.</p></form></div>`);document.getElementById('wa-new-life').addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget)),person=choices.find(p=>p.id===data.primaryPersonId);if(!person||!data.title?.trim()||!data.date)return;api.saveDraft('life',{...data,accountId:person.accountId,sourceAccountId:person.accountId,sourceKey:person.id,sourceKind:'Contact',operation:'create-proposal'});document.getElementById('record-dialog').close();});}
 function goalForm(g){proposalForm('goal','Review goal · '+g.Name,g,field('Goal name','title',g.Name)+field('Goal type','goalType',g.Type)+field('Status','status',g.Status)+field('Priority','priority',g.Priority)+field('Target date','dueDate',String(g.TargetDate||'').slice(0,10),'date')+field('Target amount (USD)','targetAmount',g.TargetAmount,'number')+field('Actual amount (USD)','actualAmount',g.ActualAmount,'number')+`<label class="wa-field">Description<textarea name="description">${E(g.Description||'')}</textarea></label>`,{accountId:g.FinancialPlan?.AccountId,financialPlanId:g.FinancialPlanId,goalId:g.Id,sourceAccountId:g.FinancialPlan?.AccountId,sourceKind:'goal',sourceKey:g.Id});}
 function leadForm(l){proposalForm('lead',l.Id?'Review lead · '+(l.Name||l.LastName):'Create lead proposal',l,field('First name','firstName',l.FirstName)+field('Last name','lastName',l.LastName)+field('Company','company',l.Company)+field('Email','email',l.Email,'email')+field('Status','status',l.Status)+field('Lead source','leadSource',l.LeadSource)+field('Annual company revenue (USD)','annualRevenue',l.AnnualRevenue,'number'),{sourceKind:'lead',sourceKey:l.Id,ownerId:l.OwnerId});}
 function commitment(r){const event=!!r.StartDateTime;modal('Source commitment · '+r.Subject,`<div class="wa"><p>${E(r.Description||'No description supplied.')}</p><div class="wa-evidence">${Object.entries(r).filter(([k])=>k!=='attributes').map(([k,v])=>`<div><span>${E(k)}</span><strong>${v==null?'Not supplied':E(v)}</strong></div>`).join('')}</div><div class="wa-actions">${btn('Propose supported edits','commitment-edit',r.Id)}${btn(event?'Propose cancellation':'Propose completion',event?'commitment-delete':'commitment-complete',r.Id)}${event?'':btn('Propose deletion','commitment-delete',r.Id)}</div><p class="wa-source">WhoId is fixed for update proposals. Event duration is fixed. These controls record intent only.</p></div>`);}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-wa]');if(!active()||!b)return;const action=b.dataset.wa,id=b.dataset.waId;if(!['commitment-edit','commitment-delete','commitment-complete'].includes(action))return;const r=[...(D.tasks||[]),...(D.events||[])].find(r=>r.Id===id);if(!r)return;if(action==='commitment-edit'){proposalForm(r.StartDateTime?'meeting':'task','Edit commitment · '+r.Subject,r,field('Subject','title',r.Subject)+(r.StartDateTime?field('Start (local time)','start',localDateTime(r.StartDateTime),'datetime-local')+field('Location','location',r.Location)+field('Show as','showAs',r.ShowAs):field('Status','status',r.Status)+field('Priority','priority',r.Priority)+field('Due date','dueDate',r.ActivityDate,'date'))+field('Activity type','type',r.Type)+field('Assigned owner ID','ownerId',r.OwnerId)+`<label class="wa-field">Description<textarea name="description">${E(r.Description||'')}</textarea></label>`,{accountId:r.WhatId?.startsWith('001')?r.WhatId:null,whoId:r.WhoId,whatId:r.WhatId,sourceKind:r.StartDateTime?'Event':'Task',sourceKey:r.Id,sourceAccountId:r.WhatId?.startsWith('001')?r.WhatId:null,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,sourceStartUtc:r.StartDateTime,duration:r.DurationInMinutes});}else{api.saveDraft(r.StartDateTime?'meeting':'task',{title:r.Subject,accountId:r.WhatId?.startsWith('001')?r.WhatId:null,whatId:r.WhatId,sourceRecordId:r.Id,sourceKind:r.StartDateTime?'Event':'Task',sourceKey:r.Id,sourceAccountId:r.WhatId?.startsWith('001')?r.WhatId:null,whoId:r.WhoId,ownerId:r.OwnerId,operation:action==='commitment-delete'?'delete-proposal':'complete-proposal',status:action==='commitment-complete'?'Completed':r.Status});document.getElementById('record-dialog').close();api.toast?.('Local commitment proposal saved.');render();}});
 return {searchRecords:()=>({accounts:D.accounts,contacts:D.accounts.filter(a=>a.PersonContactId).map(a=>({Id:a.PersonContactId,Name:a.Name,AccountId:a.Id,Email:a.PersonEmail})),leads:D.leads,opportunities:D.opportunities,cases:D.deepCases,tasks:D.tasks,events:D.events}),navLabel:(page,label)=>({health:'Review horizon',journey:'Plans & goals',growth:'Capital & acquisition',work:'My workbench'}[page]||label),accounts,offers,offersForAccount,historyFor,prepareDraft:(kind,data)=>C.prepare(data),render(page,fallback){if(!active())return null;syncRouteView();return page==='relationships'&&!state.client?directory():page==='journey'?journey():page==='today'?agenda():page==='health'?reviews():page==='growth'?growth():page==='intelligence'?intelligence():page==='work'?work(fallback):null;},relationship,recordFor(kind,id){return (kind==='goal'?D.goals:kind==='lead'?D.leads:kind==='task'?D.tasks:kind==='meeting'?D.events:kind==='life'?workspaceCapture.personas.wealth.lifeEvents:[])?.find(r=>r.Id===id)||null;},editDraft(d){return d.persona==='wealth'?editLocal(d):false;},openPreparation(){if(!state.client||!account(state.client))return false;modal('My review folio',`<div class="wa">${folio(state.client)}</div>`);return true;},openForm(kind,n,r,defaults={}){if(r?.Id&&['task','meeting'].includes(kind)){commitment(r);return true;}if(kind==='life'){r?lifeForm(r):newLife(defaults.accountId||state.client||'');return true;}if(kind==='email'){const a=account(defaults.accountId||state.client);if(a){api.openBaseForm(kind,n||a.Name,r,{...defaults,accountId:a.Id,email:defaults.email||a.PersonEmail||''});return true;}}if(kind==='goal'){r?goalForm(r):newGoal(defaults.accountId||state.client||'');return true;}if(kind==='lead'){leadForm(r||{});return true;}return false;}};
};
